def f(i):
    H,W=len(i),len(i[0])
    g=[row[:] for row in i]
    sr=max(r for r in range(H) if any(x!=0 and x!=1 for x in i[r]))
    ones={2:3,8:2}
    for c in range(W):
        v=i[sr][c]
        if v not in ones: continue
        k=ones[v]; top=sr-k-1
        for r in range(top,sr):
            g[r][c]=1
    return g
